import Database from 'better-sqlite3';
import * as fs from 'node:fs';
import * as path from 'node:path';
import * as crypto from 'node:crypto';

const PROJECT_ROOT = '/home/user/qwik-upload';
const DB_PATH = path.join(PROJECT_ROOT, 'uploads.db');
const UPLOADS_DIR = path.join(PROJECT_ROOT, 'uploads');

// Ensure uploads directory exists
if (!fs.existsSync(UPLOADS_DIR)) {
  fs.mkdirSync(UPLOADS_DIR, { recursive: true });
}

// Initialize SQLite database
const db = new Database(DB_PATH);

// Create table if it doesn't exist
db.exec(`
  CREATE TABLE IF NOT EXISTS files (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    originalName TEXT NOT NULL,
    storedName TEXT NOT NULL UNIQUE,
    size INTEGER NOT NULL,
    sha256 TEXT NOT NULL UNIQUE,
    contentType TEXT NOT NULL
  );
`);

export interface FileMetadata {
  id?: number;
  originalName: string;
  storedName: string;
  size: number;
  sha256: string;
  contentType: string;
}

export function sanitizeFilename(name: string): string {
  if (!name) return 'file';
  // Replace backslashes with forward slashes to normalize
  const normalized = name.replace(/\\/g, '/');
  // Get the last portion after the last slash
  let base = normalized.split('/').pop() || '';
  if (base === '.' || base === '..' || !base) {
    base = 'file';
  }
  return base;
}

export function detectContentType(buffer: Buffer): 'image/png' | 'application/pdf' | null {
  if (buffer.length >= 8) {
    const isPng = buffer[0] === 0x89 &&
                  buffer[1] === 0x50 &&
                  buffer[2] === 0x4E &&
                  buffer[3] === 0x47 &&
                  buffer[4] === 0x0D &&
                  buffer[5] === 0x0A &&
                  buffer[6] === 0x1A &&
                  buffer[7] === 0x0A;
    if (isPng) return 'image/png';
  }
  if (buffer.length >= 4) {
    const isPdf = buffer[0] === 0x25 &&
                  buffer[1] === 0x50 &&
                  buffer[2] === 0x44 &&
                  buffer[3] === 0x46;
    if (isPdf) return 'application/pdf';
  }
  return null;
}

export function getAllFiles(): FileMetadata[] {
  return db.prepare('SELECT originalName, storedName, size, sha256, contentType FROM files ORDER BY id DESC').all() as FileMetadata[];
}

export function getFileByStoredName(storedName: string): FileMetadata | null {
  return db.prepare('SELECT originalName, storedName, size, sha256, contentType FROM files WHERE storedName = ?').get(storedName) as FileMetadata | null;
}

export interface UploadResult {
  success: boolean;
  errorCode?: 'no_file' | 'file_too_large' | 'unsupported_type';
  dedup?: boolean;
  file?: FileMetadata;
}

export async function processUpload(
  fileData: Blob | File | null | undefined,
  clientFilename: string | null | undefined
): Promise<UploadResult> {
  // 1. Validate missing or empty file
  if (!fileData || fileData.size === 0) {
    return { success: false, errorCode: 'no_file' };
  }

  // 2. Validate size (max 1048576 bytes)
  const MAX_SIZE = 1048576;
  if (fileData.size > MAX_SIZE) {
    return { success: false, errorCode: 'file_too_large' };
  }

  // Read file data into buffer
  const arrayBuffer = await fileData.arrayBuffer();
  const buffer = Buffer.from(arrayBuffer);

  // 3. Validate content type from byte signature
  const contentType = detectContentType(buffer);
  if (!contentType) {
    return { success: false, errorCode: 'unsupported_type' };
  }

  // 4. Sanitize client-declared filename
  const rawFilename = clientFilename || (fileData as any).name || 'file';
  const originalName = sanitizeFilename(rawFilename);

  // Compute SHA-256
  const sha256 = crypto.createHash('sha256').update(buffer).digest('hex');

  // Determine server-generated stored name
  const ext = contentType === 'image/png' ? 'png' : 'pdf';
  const storedName = `${sha256}.${ext}`;
  const filePath = path.join(UPLOADS_DIR, storedName);

  // 5. Deduplicate by content
  // Check if it already exists in the database
  const existing = db.prepare('SELECT originalName, storedName, size, sha256, contentType FROM files WHERE sha256 = ?').get(sha256) as FileMetadata | null;
  if (existing) {
    return { success: true, dedup: true, file: existing };
  }

  // Write file to disk
  await fs.promises.writeFile(filePath, buffer);

  // Insert into DB
  try {
    db.prepare(`
      INSERT INTO files (originalName, storedName, size, sha256, contentType)
      VALUES (?, ?, ?, ?, ?)
    `).run(originalName, storedName, buffer.length, sha256, contentType);

    const inserted = {
      originalName,
      storedName,
      size: buffer.length,
      sha256,
      contentType
    };

    return { success: true, dedup: false, file: inserted };
  } catch (err: any) {
    // If concurrent request inserted it first, handle unique constraint
    if (err.code === 'SQLITE_CONSTRAINT' || err.code === 'SQLITE_CONSTRAINT_UNIQUE') {
      const concurrentExisting = db.prepare('SELECT originalName, storedName, size, sha256, contentType FROM files WHERE sha256 = ?').get(sha256) as FileMetadata | null;
      if (concurrentExisting) {
        return { success: true, dedup: true, file: concurrentExisting };
      }
    }
    throw err;
  }
}

export function getUploadFilePath(storedName: string): string {
  return path.join(UPLOADS_DIR, storedName);
}

import { component$ } from '@builder.io/qwik';
import { Form, routeAction$, routeLoader$ } from '@builder.io/qwik-city';
import { getAllFiles, processUpload } from '../lib/db.server';

export const useStoredFiles = routeLoader$(async () => {
  return getAllFiles();
});

export const useUploadAction = routeAction$(async (data, event) => {
  const formData = await event.request.formData();
  const file = formData.get('file') as Blob | File | null;
  const filename = formData.get('filename') as string | null;
  return await processUpload(file, filename);
});

export default component$(() => {
  const files = useStoredFiles();
  const action = useUploadAction();

  return (
    <div style={{ padding: '20px', fontFamily: 'sans-serif' }}>
      <h1>Secure File Upload Service</h1>

      <Form action={action} encType="multipart/form-data" style={{ marginBottom: '20px' }}>
        <div style={{ marginBottom: '10px' }}>
          <label style={{ display: 'block', fontWeight: 'bold' }}>File:</label>
          <input type="file" name="file" />
        </div>
        <div style={{ marginBottom: '10px' }}>
          <label style={{ display: 'block', fontWeight: 'bold' }}>Filename:</label>
          <input type="text" name="filename" placeholder="Original filename" />
        </div>
        <button type="submit">Upload</button>
      </Form>

      {action.value && (
        <div
          id="upload-result"
          data-status={action.value.success ? 'success' : 'error'}
          {...(action.value.success
            ? { 'data-dedup': action.value.dedup ? 'true' : 'false' }
            : { 'data-error-code': action.value.errorCode })}
          style={{
            padding: '10px',
            backgroundColor: action.value.success ? '#e6f4ea' : '#fce8e6',
            border: `1px solid ${action.value.success ? '#137333' : '#c5221f'}`,
            borderRadius: '4px',
            marginBottom: '20px',
          }}
        >
          {action.value.success ? (
            <div>
              <strong>Success!</strong> Stored as {action.value.file?.storedName}{' '}
              {action.value.dedup ? '(Deduplicated)' : ''}
            </div>
          ) : (
            <div>
              <strong>Error:</strong> {action.value.errorCode}
            </div>
          )}
        </div>
      )}

      <h2>Stored Files</h2>
      <div class="file-list">
        {files.value.length === 0 ? (
          <p>No files uploaded yet.</p>
        ) : (
          files.value.map((file) => (
            <div
              key={file.storedName}
              data-stored-name={file.storedName}
              style={{
                padding: '10px',
                borderBottom: '1px solid #ccc',
                display: 'flex',
                justifyContent: 'space-between',
                alignItems: 'center',
              }}
            >
              <div>
                <strong>{file.originalName}</strong> <span style={{ color: '#666' }}>({file.contentType})</span>
                <div style={{ fontSize: '0.8em', color: '#888' }}>
                  Size: {file.size} bytes | SHA-256: {file.sha256}
                </div>
              </div>
              <a href={`/api/files/download/${file.storedName}`} download={file.originalName}>
                Download
              </a>
            </div>
          ))
        )}
      </div>
    </div>
  );
});

import { type RequestHandler } from '@builder.io/qwik-city';
import { getAllFiles } from '../../../lib/db.server';

export const onGet: RequestHandler = async ({ json }) => {
  const files = getAllFiles();
  json(200, files);
};

import { type RequestHandler } from '@builder.io/qwik-city';
import { getFileByStoredName, getUploadFilePath } from '../../../../../lib/db.server';
import { Readable } from 'node:stream';
import * as fs from 'node:fs';

export const onGet: RequestHandler = async (event) => {
  const storedName = event.params.storedName;
  const file = getFileByStoredName(storedName);

  if (!file) {
    event.status(404);
    event.json(404, { error: 'File not found' });
    return;
  }

  const filePath = getUploadFilePath(storedName);
  if (!fs.existsSync(filePath)) {
    event.status(404);
    event.json(404, { error: 'File not found on disk' });
    return;
  }

  const nodeStream = fs.createReadStream(filePath);
  const webStream = Readable.toWeb(nodeStream);

  const response = new Response(webStream, {
    status: 200,
    headers: {
      'Content-Type': file.contentType,
      'Content-Disposition': `attachment; filename="${file.originalName}"`,
    },
  });

  event.send(response);
};
